#!/usr/bin/env python3\n\"\"\"\nVerify installation and show setup information.\nRun this after installing requirements.txt\n\"\"\"\n\nimport sys\nimport torch\nimport json\nfrom pathlib import Path\n\ndef print_section(title):\n    print(f\"\\n{'='*70}\")\n    print(f\" {title}\")\n    print(f\"{'='*70}\")\n\ndef verify_dependencies():\n    \"\"\"Verify all required packages are installed\"\"\"\n    print_section(\"DEPENDENCY VERIFICATION\")\n    \n    packages = [\n        ('torch', 'PyTorch'),\n        ('transformers', 'Hugging Face Transformers'),\n        ('datasets', 'Hugging Face Datasets'),\n        ('accelerate', 'Accelerate'),\n        ('numpy', 'NumPy'),\n        ('pandas', 'Pandas'),\n        ('tqdm', 'TQDM'),\n        ('nltk', 'NLTK'),\n        ('rouge_score', 'ROUGE Score'),\n    ]\n    \n    all_ok = True\n    for package, name in packages:\n        try:\n            mod = __import__(package)\n            version = getattr(mod, '__version__', 'unknown')\n            print(f\"✓ {name:30} {version}\")\n        except ImportError:\n            print(f\"✗ {name:30} NOT INSTALLED\")\n            all_ok = False\n    \n    return all_ok\n\ndef verify_custom_modules():\n    \"\"\"Verify custom modules can be imported\"\"\"\n    print_section(\"CUSTOM MODULES VERIFICATION\")\n    \n    sys.path.insert(0, '/home/houssem/BugFixer/src')\n    \n    modules = [\n        ('data_processing.real_bug_loader', 'Real Bug Loader'),\n        ('data_processing.advanced_preprocessor', 'Advanced Preprocessor'),\n        ('model.enhanced_architecture', 'Enhanced Architecture'),\n        ('model.optimized_trainer', 'Optimized Trainer'),\n        ('evaluation.comprehensive_evaluator', 'Evaluator'),\n        ('model.production_inference', 'Production Inference'),\n    ]\n    \n    all_ok = True\n    for module_path, name in modules:\n        try:\n            __import__(module_path)\n            print(f\"✓ {name:30}\")\n        except Exception as e:\n            print(f\"✗ {name:30} {str(e)[:40]}\")\n            all_ok = False\n    \n    return all_ok\n\ndef check_gpu():\n    \"\"\"Check GPU availability and properties\"\"\"\n    print_section(\"GPU VERIFICATION\")\n    \n    print(f\"CUDA available: {torch.cuda.is_available()}\")\n    \n    if torch.cuda.is_available():\n        print(f\"CUDA version: {torch.version.cuda}\")\n        print(f\"\\nAvailable GPUs:\")\n        for i in range(torch.cuda.device_count()):\n            props = torch.cuda.get_device_properties(i)\n            print(f\"  GPU {i}: {props.name}\")\n            print(f\"    Memory: {props.total_memory / 1024**3:.1f} GB\")\n            print(f\"    Compute Capability: {props.major}.{props.minor}\")\n        \n        # Check mixed precision support\n        print(f\"\\nMixed Precision (AMP) available: {hasattr(torch.cuda, 'amp')}\")\n        return True\n    else:\n        print(\"No GPU detected. CPU training will be slow.\")\n        return False\n\ndef check_file_structure():\n    \"\"\"Verify file structure\"\"\"\n    print_section(\"FILE STRUCTURE VERIFICATION\")\n    \n    base_dir = Path('/home/houssem/BugFixer')\n    required_files = [\n        'src/data_processing/real_bug_loader.py',\n        'src/data_processing/advanced_preprocessor.py',\n        'src/model/enhanced_architecture.py',\n        'src/model/optimized_trainer.py',\n        'src/evaluation/comprehensive_evaluator.py',\n        'src/model/production_inference.py',\n        'training_pipeline.ipynb',\n        'test_cases.py',\n        'requirements.txt',\n        'README_PRODUCTION.md',\n        'IMPLEMENTATION_SUMMARY.md',\n    ]\n    \n    all_ok = True\n    for file_path in required_files:\n        full_path = base_dir / file_path\n        if full_path.exists():\n            size = full_path.stat().st_size\n            print(f\"✓ {file_path:50} ({size:,} bytes)\")\n        else:\n            print(f\"✗ {file_path:50} MISSING\")\n            all_ok = False\n    \n    return all_ok\n\ndef show_version_info():\n    \"\"\"Show version information\"\"\"\n    print_section(\"VERSION INFORMATION\")\n    \n    info = {\n        'Python': f\"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}\",\n        'PyTorch': torch.__version__,\n        'CUDA': torch.version.cuda or 'N/A',\n        'CUDNN': torch.version.cudnn or 'N/A',\n    }\n    \n    try:\n        import transformers\n        info['Transformers'] = transformers.__version__\n    except:\n        pass\n    \n    for key, value in info.items():\n        print(f\"{key:20}: {value}\")\n\ndef show_setup_instructions():\n    \"\"\"Show next steps\"\"\"\n    print_section(\"NEXT STEPS\")\n    \n    print(\"\"\"\n1. Run the training notebook:\n   \n   cd /home/houssem/BugFixer\n   jupyter notebook training_pipeline.ipynb\n   \n   Then run all cells in order. Expected time: 6-8 hours on Tesla T4.\n\n2. After training, evaluate results:\n   \n   python3 -c \"from test_cases import RealBugTestCases; \\\n               RealBugTestCases.get_statistics()\"\n   \n3. For inference:\n   \n   from src.model.production_inference import ProductionInference\n   from transformers import AutoTokenizer, AutoModelForSeq2SeqLM\n   import torch\n   \n   device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')\n   model = AutoModelForSeq2SeqLM.from_pretrained('./output/final_model')\n   tokenizer = AutoTokenizer.from_pretrained('./output/final_model')\n   \n   inference = ProductionInference(model, tokenizer, device)\n   result = inference.predict_single(\"for(int i=0; i<=n; i++) { }\")\n   print(result.predicted_code)\n   \n4. For more information:\n   - README_PRODUCTION.md - Complete guide with 2000+ lines\n   - IMPLEMENTATION_SUMMARY.md - What was implemented\n   - test_cases.py - 20 real bug examples\n\"\"\")\n\ndef main():\n    \"\"\"Run all verifications\"\"\"\n    print(\"\\n\")\n    print(\"╔════════════════════════════════════════════════════════════════╗\")\n    print(\"║  Java Bug-Fixing Model - Installation Verification             ║\")\n    print(\"╚════════════════════════════════════════════════════════════════╝\")\n    \n    # Run checks\n    checks = [\n        (\"Dependencies\", verify_dependencies),\n        (\"Custom Modules\", verify_custom_modules),\n        (\"GPU\", check_gpu),\n        (\"File Structure\", check_file_structure),\n    ]\n    \n    results = {}\n    for check_name, check_func in checks:\n        try:\n            results[check_name] = check_func()\n        except Exception as e:\n            print(f\"\\n✗ Error during {check_name} check: {e}\")\n            results[check_name] = False\n    \n    # Show additional info\n    show_version_info()\n    \n    # Summary\n    print_section(\"VERIFICATION SUMMARY\")\n    \n    all_passed = all(results.values())\n    for check_name, result in results.items():\n        status = \"✓ PASS\" if result else \"✗ FAIL\"\n        print(f\"{status:10} {check_name}\")\n    \n    if all_passed:\n        print(\"\\n✓ All checks passed! System is ready for training.\")\n    else:\n        print(\"\\n✗ Some checks failed. Please install missing dependencies.\")\n        print(\"  Run: pip install -r requirements.txt\")\n    \n    # Show next steps\n    show_setup_instructions()\n    \n    print(\"\\n\" + \"=\"*70 + \"\\n\")\n    \n    return 0 if all_passed else 1\n\nif __name__ == '__main__':\n    sys.exit(main())\n